/*
 * Everything the coach needs to look after one learner, and to build their plan (DBU-04).
 * Unlike myPlan this returns unshared steps and CoachNote rows: it is staff-only for that
 * reason. The plan templates ride along (not archived) because the plan builder on the same
 * page offers them, and `plan.templateTitle` names the one the plan was started from.
 * `checkins` (DBU-10): every check-in she answered, each with the form it answered (its own copy).
 */
(async () => {
  try {
    const id = String(Inputs.learnerId || '');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const pick = (row, fields) => {
      const out = { id: row.objectId };
      fields.forEach((f) => { out[f] = row[f] === undefined ? null : row[f]; });
      return out;
    };
    const users = id ? await q('_User', { objectId: { equalTo: id } }) : [];
    if (users.length !== 1) throw new Error('no learner ' + id);

    const plans = await q('Plan', { learner: { equalTo: id } });
    const byStart = plans.slice().sort((a, b) => String(b.startedOn).localeCompare(String(a.startedOn)));
    const plan = plans.find((p) => p.status === 'active') || byStart[0] || null;
    const steps = plan ? (await q('Step', { plan: { equalTo: plan.objectId } })).sort((a, b) => a.position - b.position) : [];
    const subs = await q('Submission', { learner: { equalTo: id } });
    const notes = await q('CoachNote', { learner: { equalTo: id } });
    const templates = await q('PlanTemplate', {});
    const responses = await q('CheckinResponse', { learner: { equalTo: id } });

    Outputs.learner = pick(users[0], ['name', 'email', 'organisation', 'jobTitle', 'timezone', 'lastSeenAt']);
    Outputs.plans = byStart.map((p) => pick(p, ['title', 'status', 'startedOn', 'fromTemplate']));
    Outputs.plan = plan ? Object.assign(pick(plan, ['title', 'status', 'meetingLink', 'bookingLink', 'startedOn', 'fromTemplate']), {
      templateTitle: (templates.find((t) => t.objectId === plan.fromTemplate) || {}).title || ''
    }) : null;
    Outputs.steps = steps.map((s) => pick(s, [
      'position', 'kind', 'title', 'shared', 'status', 'startsAt', 'durationMin', 'meetingLink', 'prepNote', 'attended',
      'recordingUrl', 'summary', 'dueAt', 'brief', 'handInChecklist', 'resources', 'fromLibraryItem', 'form', 'sendsAt',
      'sendAfter', 'sentAt'
    ]));
    Outputs.submissions = subs
      .map((s) => Object.assign(pick(s, ['step', 'version', 'kind', 'files', 'url', 'text', 'note', 'review', 'reviewNote', 'reviewedAt']), { handedInAt: s.createdAt }))
      .sort((a, b) => a.version - b.version);
    Outputs.notes = notes.map((n) => Object.assign(pick(n, ['body']), { writtenAt: n.createdAt }));
    Outputs.templates = templates
      .filter((t) => t.archived !== true)
      .map((t) => ({ id: t.objectId, title: t.title || '', steps: Array.isArray(t.items) ? t.items.length : 0 }))
      .sort((a, b) => a.title.localeCompare(b.title));
    Outputs.checkins = responses.map((r) => {
      const step = steps.find((s) => s.objectId === r.step);
      return { id: r.objectId, step: r.step, answers: r.answers || {}, form: r.form || (step && step.form) || { questions: [] }, answeredAt: r.createdAt, seenAt: r.seenAt || null };
    });
    Outputs.done();
  } catch (e) {
    console.error('[dbu:learnerAsCoach]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
